package io.xeros.solo;
import io.xeros.*;import io.xeros.model.definitions.*;import io.xeros.content.combat.weapon.*;import io.xeros.content.combat.specials.Specials;import com.google.gson.*;import java.nio.file.*;import java.util.*;
public final class EquipmentInventory69 {
 public static void main(String[]a)throws Exception{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();List<Map<String,Object>> all=new ArrayList<>();for(ItemDef d:ItemDef.getDefinitions().values()){int id=d.getId(),slot=ItemStats.forId(id).getEquipment().getSlot();if(d.isNoted()||d.getName()==null||slot<0)continue;Map<String,Object> row=new LinkedHashMap<>();row.put("id",id);row.put("name",d.getName());row.put("slot",slot);row.put("weapon_family",slot==3?WeaponData.forItemId(id).name():"");row.put("requirements",d.getRequirements().toString());all.add(row);}all.sort(Comparator.comparingInt(x->(Integer)x.get("id")));Files.writeString(Path.of(a.length>0?a[0]:"D:/Games/OSRS/relatorios/combate-v69/inventario-equipamentos.json"),new GsonBuilder().setPrettyPrinting().create().toJson(all));for(int id:new int[]{27275,27277,26219,27246,22325,22486,25736,25739,25862,25865,25867,23842,23845,23848,23971,23975,23979,27226,27229,27232,27235,27238,27241,26382,26384,26386})System.out.println(id+" "+ItemDef.forId(id).getName()+" SLOT "+ItemStats.forId(id).getEquipment().getSlot()+" FAMILY "+WeaponData.forItemId(id));System.out.println("EQUIPMENT_INVENTORY68_PASS COUNT="+all.size());System.exit(0);}
}
